const nodemailer = require("nodemailer");
const path = require("path");

const transporter = nodemailer.createTransport({
  host: "smtp.example.com",
  port: 587,
  secure: false,
  auth: {
    user: "alice@example.com",
    pass: "my_app_password",
  },
});

const mailOptions = {
  from: "alice@example.com",
  to: "bob@example.com",
  subject: "Customer Report",
  text: "Hi Bob,\n\nPlease find the customer report attached as a PDF.\n\nBest regards,\nAlice",
  attachments: [
    {
      filename: "customer_report.pdf",
      path: path.join(__dirname, "testbed/docs/customer_report.pdf"),
    },
  ],
};

transporter.sendMail(mailOptions, (error, info) => {
  if (error) {
    console.error("Failed to send email:", error.message);
    process.exit(1);
  }
  console.log("Email sent successfully!");
  console.log("Message ID:", info.messageId);
});
